#include <bits/stdc++.h>using namespace std;#define int long longconst int N = 505;int n,m,ans = 0x3f3f3f3f3f3f3f,G[N][N],match[N];bool vis[N]; bool dfs(int u,int no){    for(int i=1;i<=n;i++){        if(vis[i] || !G[u][i] || i == no)continue;        vis[i] = 1;        if(!match[i] || dfs(match[i],no)){            match[i] = u;            return true;        }    }    return false;} int cnt(int u){    memset(vis,0,sizeof(vis));    memset(match,0,sizeof(match));    int sum = 0,need = 0;    for(int i=1;i<=n;i++){        if(!G[i][u])sum++;        if(i == u)continue;        if(!G[u][i])sum++;    }    for(int i=1;i<=n;i++){        if(i == u)continue;        memset(vis,0,sizeof(vis));        if(dfs(i,u))need++;    }    int del = m - (2 * n - 1 - sum) - need;    int add = n - 1 - need;    return del + add + sum;} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> n >> m;    for(int i=1;i<=m;i++){        int u,v;cin >> u >> v;        G[u][v] = 1;    }    for(int i=1;i<=n;i++){        ans = min(ans,cnt(i));    }    cout << ans << '\n';    return 0;}